-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- dispatch_owner_safety_notice(p_estate) → text                               [admin, AAL2+fresh]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ PHASE 11-F, D4 — "the owner was told" MUST mean an independently reachable channel. 11-E wrote
-- one in-app notification and required it to commit; that is a real guarantee and it is not enough,
-- because a person who has stopped opening the app is exactly the person a false death process
-- targets successfully. This routine additionally commits an EMAIL row addressed to the owner, in
-- the SAME transaction as the state change, and refuses the whole transition if it cannot.
--
-- ★ THE REQUIREMENT IS DISPATCH INITIATION, NOT DELIVERY (Stage 2, stated exactly). No read
-- receipt, no open tracking, no acknowledgement — none of which this product can honestly observe,
-- and each of which would let a silent mail server hold a release hostage forever. What IS required
-- is that a real address was resolved and a real row was committed to a real queue.
--
-- ★ AND AN UNRESOLVABLE ADDRESS IS A HARD FAILURE. Queueing a row with no recipient would be
-- "dispatch initiated" in name only — the fail-closed answer is to refuse the transition, leaving
-- the estate at `death_verified` where nothing can release, rather than starting a clock nobody can
-- hear ticking.
--
-- ★ D2 — `owner_notified_at` IS STAMPED HERE, AND SINCE PHASE 11-OC / PHASE D IT IS PROVENANCE
-- RATHER THAN THE RELEASE CLOCK. It records the instant the operator initiated dispatch — not claim
-- creation, evidence upload, verification or administrative review, none of which the owner can see
-- — and that remains the right fact for this row to carry. What it is NOT is proof that a message
-- left the building: it is written when the outbox row is QUEUED, before any worker has run. The
-- seven days now run from `notice_accepted_at` on the accepted notice; see
-- `owner_notice_release_authority`. This routine is unchanged by Phase D.
create or replace function public.dispatch_owner_safety_notice(p_estate uuid)
 returns text
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid       uuid;
  v_state     text;
  v_owner     uuid;
  v_recipient text;
  v_case      uuid;
  v_notice    uuid;
  v_outbox    uuid;
begin
  perform public.admin_require_gate();
  v_uid := auth.uid();

  select l.state into v_state
    from public.estate_lifecycle l
   where l.estate_id = p_estate
   for update;

  if v_state = 'owner_notification_dispatched' then
    return 'owner_notification_dispatched'; -- idempotent replay: no re-dispatch, no re-audit
  end if;
  if v_state is distinct from 'death_verified' then
    raise exception 'invalid_dispatch_state' using errcode = 'P0001';
  end if;

  select c.id into v_case
    from public.death_verification_cases c
   where c.estate_id = p_estate and c.status = 'verified'
   order by c.decided_at desc
   limit 1;
  if v_case is null then
    raise exception 'no_verified_case' using errcode = 'P0001';
  end if;

  v_owner := public.estate_owner_user_id(p_estate);
  if v_owner is null then
    raise exception 'owner_unresolved' using errcode = 'P0001';
  end if;

  -- ★ THE INDEPENDENT CHANNEL, RESOLVED FROM THE IDENTITY PROVIDER rather than from anything a
  -- claimant can write. `profiles.email` is user-editable in principle; `auth.users.email` is the
  -- address the account authenticates with, which is the one a claimant cannot repoint.
  select u.email into v_recipient from auth.users u where u.id = v_owner;
  if v_recipient is null or btrim(v_recipient) = '' then
    raise exception 'owner_channel_unreachable' using errcode = 'P0001';
  end if;

  -- EMAIL FIRST: the row whose existence is the dispatch. Same transaction as the transition, so a
  -- rollback anywhere below un-dispatches it and the window never opened.
  -- ★ PHASE 11-OC — THE ROW NAMES ITS EPISODE, AND `v_case` WAS ALREADY IN HAND.
  --
  -- `v_case` is resolved above and, until this phase, was discarded into the audit metadata only. It
  -- is the EPISODE key: one estate may legitimately experience several independent death processes
  -- over time (`rejected` and `cancelled` both return the lifecycle to `active`), so an accepted
  -- notice from a prior, rejected process must never authorize a release under a later case. Scoping
  -- the release predicate to the estate would do exactly that; scoping it to the case cannot.
  --
  -- `generation` is the literal 1 here and only ever incremented by the re-notice routine, under the
  -- predecessor's row lock — never from an unlocked max().
  --
  -- A BEFORE INSERT trigger (migration 0058) refuses any owner-notice row with a NULL case_id, so
  -- this is a wall rather than a promise this routine makes. Legacy rows keep their NULL and stay
  -- updatable, because the trigger fires on INSERT only.
  insert into public.owner_notice_outbox
    (estate_id, user_id, channel, recipient, notice_kind, status, case_id, generation)
  values (p_estate, v_owner, 'email', v_recipient, 'death_process.window_opened', 'queued',
          v_case, 1)
  returning id into v_outbox;
  if v_outbox is null then
    raise exception 'owner_notification_failed' using errcode = 'P0001';
  end if;

  -- IN-APP SECOND, and still REQUIRED (11-E's guarantee is kept, not replaced). Two channels, both
  -- committed, before any clock starts.
  v_notice := public.emit_lifecycle_notification(
    v_owner, p_estate, 'death_process.window_opened', 'afterworth://challenge');
  if v_notice is null then
    raise exception 'owner_notification_failed' using errcode = 'P0001';
  end if;

  perform public.apply_estate_lifecycle_transition(
    p_estate, 'owner_notification_dispatched', v_case, 'owner_notice_dispatched');

  update public.estate_lifecycle
     set owner_notified_at = now(),
         safety_notification_id = v_notice
   where estate_id = p_estate;

  -- ★ THE AUDIT RECORDS THE CHANNEL CLASS, NEVER THE ADDRESS. That a notice went to email is an
  -- operational fact; WHICH address is a living owner's contact detail, and an audit row outlives
  -- every reason anyone had to read it.
  insert into public.audit_logs (actor_id, estate_id, action, target_table, target_id, metadata, source)
  values (v_uid, p_estate, 'death_process.owner_notice_dispatched', 'owner_notice_outbox', v_outbox,
          jsonb_build_object('severity', 'high', 'case_id', v_case, 'channel', 'email',
                            'in_app_notification_id', v_notice),
          'admin');
  return 'owner_notification_dispatched';
end $function$;
revoke execute on function public.dispatch_owner_safety_notice(uuid) from public, anon;
grant  execute on function public.dispatch_owner_safety_notice(uuid) to authenticated;

comment on function public.dispatch_owner_safety_notice(uuid) is
  'Phase 11-F (D4): commits an EMAIL row and an in-app notice to the owner, in the same transaction '
  'as the death_verified -> owner_notification_dispatched transition, and stamps owner_notified_at '
  '(D2: the challenge clock starts at dispatch). Requires dispatch INITIATION, never delivery '
  'confirmation. An unresolvable owner address refuses the transition. Admin-gated; idempotent.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- owner_notice_release_authority(p_case) → jsonb                                       [INTERNAL]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ PHASE 11-OC · PHASE D — THE ONE PLACE THE RELEASE DOOR'S OWNER-NOTICE AUTHORITY IS DECIDED.
--
-- Before this phase, `authorize_release` asked TWO questions in two places and got the wrong answer
-- to both. It asked "does an email row exist for this ESTATE with `status <> 'cancelled'`" — a
-- predicate nothing in production can falsify, because `dispatch_owner_safety_notice` inserts that
-- row in the same transaction as the transition and no production path ever writes `'cancelled'`.
-- And it measured the seven days from `owner_notified_at`, which is stamped when the row is QUEUED:
-- the clock ran while the message sat unsent, and kept running when the provider rejected it.
--
-- Phase D replaces both with ONE fact the database can actually prove:
--
--        THE CURRENT GENERATION OF THE CURRENT CASE EPISODE HAS `notice_accepted_at`.
--
-- ★ WHAT THAT FACT IS, AND WHAT IT IS NOT — stated here because this is the last place anybody
-- reads before trusting it. `notice_accepted_at` is stamped by exactly one branch of exactly one
-- routine (`record_owner_notice_outcome`, `providerAccepted`). It means the EMAIL PROVIDER ACCEPTED
-- THE MESSAGE FOR DELIVERY. It is **not** delivered, not received, not opened, not read, and no
-- caller, projection, console label or document may rename it into any of those. It is the
-- strongest persisted provider fact this system currently has, and Phase D protects on that rather
-- than on a weaker one — never on a stronger one it cannot observe.
--
-- ★ IT IS A SEPARATE FUNCTION FOR THE `owner_notice_reissue_assessment` REASON, WHICH IS NOT
-- TIDINESS. Three callers need this verdict: the release door, the operator case file, and the
-- deployment verifier. A second opinion in any of them — a status list in a projection, a `case`
-- expression in the case file, a TypeScript mirror in the console — is a policy that drifts, and
-- the failure mode is an operator being offered a release the server refuses, or (far worse) a
-- console that says READY while the door's own rule says otherwise. So the door and the projection
-- call the SAME function, and `db/tests/release_safety_authorization.sql` §12 asserts they agree on
-- every fixture rather than assuming they must.
--
-- ★ FOUR INDEPENDENT AUTHORITIES, AND EVERY ONE OF THEM MUST HOLD.
--
--   1. EPISODE  — the notice must belong to the CURRENT death-verification case (D3). One estate may
--                 legitimately run several death processes over time: `rejected` and `cancelled`
--                 both return the lifecycle to `active`, and a later case opens a new episode. An
--                 accepted notice from a PRIOR, REJECTED process authorizing a release under a NEW
--                 case is the estate-scope defect this whole phase exists to close. The canonical
--                 case is re-resolved HERE from the estate and the caller's `p_case` is compared
--                 against it — never trusted as the episode.
--
--   2. GENERATION — the notice must be the STRUCTURALLY current generation (D4): the row nothing
--                 supersedes. `superseded_by is null`, which is a partial-unique-indexed wall, not
--                 `max(generation)`, not `max(requested_at)`, not "the newest timestamp", not array
--                 order. A derived-max invariant cannot be expressed as a constraint, so a door
--                 resting on one rests on an invariant only the writer maintains.
--
--   3. ACCEPTANCE — `notice_accepted_at is not null` on that row (D1). NOT `status = 'dispatched'`,
--                 NOT `status <> 'cancelled'`, NOT a status allow-list of any shape. The authority
--                 is VOCABULARY-INDEPENDENT on purpose: a seventh status added to the CHECK
--                 constraint tomorrow must not become release-qualifying merely by not being
--                 `'cancelled'`, and it cannot, because no status string appears in this decision.
--
--   4. CLOCK   — `now() > notice_accepted_at + challenge_window_duration()`, STRICTLY (D5). At the
--                 exact boundary instant this refuses and the owner's challenge — serialized on the
--                 same lifecycle row lock — still succeeds. `owner_notified_at` is PROVENANCE and is
--                 never the anchor; there is deliberately no `coalesce` from one to the other,
--                 because a fallback would silently restore the defective clock for exactly the
--                 legacy population Phase D exists to refuse.
--
-- ★ CURRENT-GENERATION-ONLY AND EPISODE-EXISTENTIAL AGREE ON EVERY REACHABLE STATE, AND THAT WAS
-- PROVEN BY READING THE SETTLE PATH RATHER THAN ASSUMED. `owner_notice_release_readiness_census`
-- reads acceptance as an existential over the whole episode, and argues — correctly — that
-- authority must be MONOTONE: if issuing a re-notice could REMOVE release authority, an operator
-- would hold a lever that suppresses a release. This function reads only the current generation,
-- which looks like it breaks that property. It does not, and the reason is structural:
--
--   · `record_owner_notice_outcome` no-ops on any row already `dispatched`, `outcomeUncertain`,
--     `failedPermanent` or `cancelled`, so a settled row can never gain an acceptance stamp.
--   · `owner_notice_reissue_assessment` permits a re-notice ONLY when the current generation is
--     `failedPermanent`, `outcomeUncertain`, or `dispatched` with NULL acceptance — all settled,
--     all NULL-acceptance at the instant of supersession. `queued` and `processing` (the only rows
--     that can still gain acceptance) are refused, so they are never superseded.
--
-- Therefore a superseded row carrying `notice_accepted_at` is UNREACHABLE through the deployed
-- doors, the two readings can differ only on a state the system cannot produce, and reading the
-- current generation costs no monotonicity. It is nevertheless read strictly, because D4 asks for
-- the structural invariant rather than for an argument that the loose one happens to be safe — and
-- §12 mutation-proves that a hand-written superseded acceptance authorizes NOTHING.
--
-- ★ IT FAILS CLOSED, AND EVERY REFUSAL HAS A NAME FROM A CLOSED SET. There is no fall-through: a
-- state this ladder does not recognise lands on an explicit code rather than joining a neighbouring
-- branch. `notice_never_accepted` is deliberately NOT called `notice_not_delivered` — mailbox
-- delivery is not known to this system and naming it would be the console inventing the one fact
-- this phase exists to stop being invented.
--
-- ★ IT DISCLOSES NO IDENTITY. No recipient address, no owner user id, no estate name, no provider
-- secret. Row ids, a generation number, two timestamps and a code — the facts an operator needs to
-- know whether a release call will be refused, and nothing that describes a living person.
create or replace function public.owner_notice_release_authority(p_case uuid)
 returns jsonb
 language plpgsql
 security definer
 stable
 set search_path to 'public'
as $function$
declare
  v_c         public.death_verification_cases%rowtype;
  v_state     text;
  v_canonical uuid;
  v_row       public.owner_notice_outbox%rowtype;
  v_duration  interval;
  v_eligible  timestamptz;
  v_elapsed   boolean := false;
  v_refusal   text;
begin
  if p_case is null then
    return jsonb_build_object('ready', false, 'refusal_code', 'case_not_found',
                              'window_configured', false, 'elapsed', false);
  end if;

  select * into v_c from public.death_verification_cases c where c.id = p_case;
  if not found then
    return jsonb_build_object('ready', false, 'refusal_code', 'case_not_found',
                              'window_configured', false, 'elapsed', false);
  end if;

  -- AUTHORITY 1 · THE EPISODE. Resolved canonically from the ESTATE and compared against the
  -- caller's case — the identical derivation `authorize_release`, `dispatch_owner_safety_notice`,
  -- `owner_notice_reissue_assessment` and the readiness census all use. A caller cannot nominate an
  -- episode, so a historical case cannot be handed in as if it were current.
  select c.id into v_canonical
    from public.death_verification_cases c
   where c.estate_id = v_c.estate_id and c.status = 'verified'
   order by c.decided_at desc
   limit 1;

  select l.state into v_state from public.estate_lifecycle l where l.estate_id = v_c.estate_id;
  v_state := coalesce(v_state, 'active');

  -- AUTHORITY 2 · THE CURRENT GENERATION. Structural — `superseded_by is null` — never a max().
  -- The kind SET comes from `owner_notice_episode_kinds()` rather than a literal, for the reason
  -- Phase C gives: a literal here could not see a re-notice, so a remediated estate would be
  -- refused by the door that its remedy was built to unblock.
  select * into v_row
    from public.owner_notice_outbox o
   where o.case_id = p_case
     and o.channel = 'email'
     and o.notice_kind = any (public.owner_notice_episode_kinds())
     and o.superseded_by is null
   limit 1;

  v_duration := public.challenge_window_duration();

  -- AUTHORITY 4 · THE CLOCK, computed before the ladder so the projection can render the facts even
  -- on a branch that refuses. STRICT `>`; the coalesce is the three-valued-logic discipline — a NULL
  -- comparison must refuse, not pass.
  if v_row.notice_accepted_at is not null and v_duration is not null then
    v_eligible := v_row.notice_accepted_at + v_duration;
    v_elapsed  := coalesce(now() > v_eligible, false);
  end if;

  -- ── THE REFUSAL LADDER, IN THE ORDER THE DOOR APPLIES IT ─────────────────────────────────────
  if v_canonical is null then
    v_refusal := 'no_verified_case';
  elsif v_canonical <> p_case then
    -- A historical case on an estate that has moved on, or a case that was never verified. Either
    -- way the accepted notice it may carry authorizes NOTHING under the current process.
    v_refusal := 'notice_episode_mismatch';
  elsif v_state is distinct from 'challenge_window' then
    -- The release door's own state guard, restated here so the projection refuses for the same
    -- reason the routine will. `challenge_halted` lands here: release can never proceed from a halt.
    v_refusal := 'invalid_release_state';
  elsif v_row.id is null then
    -- No notice names this episode at all. Fail closed: an estate with no provable notice is not an
    -- estate whose owner was warned. Pre-Phase-A rows carry a NULL case_id and land here by design —
    -- they belong to no provable episode and are never guessed into one.
    v_refusal := 'no_current_notice';
  elsif v_row.notice_accepted_at is null then
    -- AUTHORITY 3 · THE LEGACY / UNSETTLED CLASS (D6). Covers every non-accepted shape at once and
    -- WITHOUT consulting a status string: `queued` (never sent), `processing` (never settled),
    -- `outcomeUncertain` (unknown), `failedPermanent` (definitively failed), `cancelled`, a
    -- pre-Phase-A `dispatched` row whose stamp did not exist, and any seventh status a future CHECK
    -- constraint admits. The remedy is a Phase C re-notice that PRODUCES the fact, never a backfill
    -- that invents one and never a manual UPDATE of a safety table.
    v_refusal := 'notice_never_accepted';
  elsif v_duration is null then
    -- NULL duration means NOT CONFIGURED, which means the window never elapses and release refuses.
    v_refusal := 'release_window_not_configured';
  elsif not v_elapsed then
    v_refusal := 'release_window_not_elapsed';
  end if;

  return jsonb_build_object(
    'ready',               v_refusal is null,
    'refusal_code',        v_refusal,
    'case_id',             p_case,
    'case_is_current',     v_canonical is not null and v_canonical = p_case,
    'lifecycle_state',     v_state,
    'notice_id',           v_row.id,
    'generation',          v_row.generation,
    'notice_kind',         v_row.notice_kind,
    -- THE FACT. NULL is a real answer and every consumer must render it as one.
    'notice_accepted_at',  v_row.notice_accepted_at,
    'accepted',            v_row.id is not null and v_row.notice_accepted_at is not null,
    'window_duration',     v_duration::text,
    'window_configured',   v_duration is not null,
    -- Anchored on ACCEPTANCE, never on owner_notified_at. NULL until there is an acceptance fact to
    -- anchor on, which is the honest answer rather than a date computed from provenance.
    'release_eligible_at', v_eligible,
    'elapsed',             v_elapsed);
end $function$;
revoke execute on function public.owner_notice_release_authority(uuid)
  from public, anon, authenticated;

comment on function public.owner_notice_release_authority(uuid) is
  'THE owner-notice release authority (Phase 11-OC / Phase D), consumed by both authorize_release '
  'and the operator case-file projection so the console can never offer a release the door refuses. '
  'A release qualifies ONLY when the CURRENT generation (superseded_by is null) of the CURRENT case '
  'episode carries notice_accepted_at, and now() > that instant + challenge_window_duration() '
  'STRICTLY. No status string participates in the decision, so a future status cannot become '
  'release-qualifying by not being cancelled. notice_accepted_at is PROVIDER ACCEPTANCE and never '
  'mailbox delivery; owner_notified_at is provenance and is never the clock. Every refusal carries '
  'a NAMED code from a closed set. Discloses no address and no identity. INTERNAL.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- begin_challenge_window(p_estate) → text                                      [admin, AAL2+fresh]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ REWRITTEN IN 11-F: it no longer notifies, because it no longer can. The notice moved to
-- `dispatch_owner_safety_notice`, and the edge `death_verified → challenge_window` was DELETED from
-- the transition map — so this routine's only legal input is an estate whose owner has already been
-- sent an email and an in-app notice. The guarantee "no window opens un-notified" is now carried by
-- the state machine rather than by this function remembering to check.
--
-- ★ PHASE D CORRECTS ITS INERT PREDICATE AND DELIBERATELY DOES **NOT** IMPORT THE RELEASE POLICY.
--
-- This door used to ask for an email row on the ESTATE with `status <> 'cancelled'` — the same
-- vacuous test the release door carried, and inert for the same reason. Phase D replaces it with
-- the fact it actually needs: A COMMITTED OWNER-SAFETY EMAIL NOTICE EXISTS FOR THE CURRENT CASE
-- EPISODE. Case-scoped, so an accepted notice from a PRIOR death process cannot satisfy it; the
-- current generation, so the check anchors on the same structural invariant the release door uses.
--
-- ★ AND IT MUST NOT REQUIRE `notice_accepted_at` (D7). Opening the window releases NOTHING — no
-- grant activates, no tier changes, no document becomes readable; the lifecycle moves and the
-- owner's challenge becomes available. The initial notice is normally still `queued` at this instant
-- because the drain runs asynchronously, so requiring provider acceptance here would make the window
-- unopenable until a worker had run, and would gate the owner's own protection on an email provider.
-- The irreversible door is `authorize_release`, and that is the one Phase D tightens.
create or replace function public.begin_challenge_window(p_estate uuid)
 returns text
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid   uuid;
  v_state text;
  v_case  uuid;
  v_row   public.estate_lifecycle%rowtype;
begin
  perform public.admin_require_gate();
  v_uid := auth.uid();

  select l.* into v_row
    from public.estate_lifecycle l
   where l.estate_id = p_estate
   for update;
  v_state := v_row.state;

  if v_state = 'challenge_window' then
    return 'challenge_window'; -- idempotent replay
  end if;
  if v_state is distinct from 'owner_notification_dispatched' then
    raise exception 'invalid_window_state' using errcode = 'P0001';
  end if;

  -- Belt beside the state machine: the dispatch facts must actually be on the row.
  if v_row.owner_notified_at is null or v_row.safety_notification_id is null then
    raise exception 'owner_not_notified' using errcode = 'P0001';
  end if;

  -- ★ THE EPISODE IS RESOLVED BEFORE THE NOTICE IS LOOKED FOR, AND THAT ORDER IS THE FIX. The
  -- pre-Phase-D body checked the outbox by ESTATE and resolved the case afterwards, so a notice
  -- belonging to any death process this estate had ever run satisfied the guard.
  select c.id into v_case
    from public.death_verification_cases c
   where c.estate_id = p_estate and c.status = 'verified'
   order by c.decided_at desc
   limit 1;
  if v_case is null then
    raise exception 'no_verified_case' using errcode = 'P0001';
  end if;

  -- ★ PHASE D (D7) — A COMMITTED EMAIL NOTICE FOR **THIS** EPISODE, AND NOTHING STRONGER.
  --
  -- Case-scoped, so a notice from a prior rejected process cannot open a window under a new case.
  -- Current generation (`superseded_by is null`), so this anchors on the same structural invariant
  -- the release door uses — and, because supersession always writes a successor, "a current
  -- generation exists" is equivalent to "any generation exists" for the episode. NO status string
  -- and NO `notice_accepted_at`: the initial dispatch is normally still `queued` at this instant
  -- (the drain is asynchronous), and gating the owner's own protection on a provider would be a
  -- release-door policy applied to a door that discloses nothing.
  if not exists (
    select 1 from public.owner_notice_outbox o
     where o.case_id = v_case
       and o.channel = 'email'
       and o.notice_kind = any (public.owner_notice_episode_kinds())
       and o.superseded_by is null
  ) then
    raise exception 'no_current_notice' using errcode = 'P0001';
  end if;

  perform public.apply_estate_lifecycle_transition(
    p_estate, 'challenge_window', v_case, 'window_opened');

  update public.estate_lifecycle
     set challenge_window_started_at = now()
   where estate_id = p_estate;

  insert into public.audit_logs (actor_id, estate_id, action, target_table, target_id, metadata, source)
  values (v_uid, p_estate, 'death_process.window_opened', 'estate_lifecycle', v_case,
          jsonb_build_object('severity', 'high', 'case_id', v_case,
                            'owner_notified_at', v_row.owner_notified_at),
          'admin');
  return 'challenge_window';
end $function$;
revoke execute on function public.begin_challenge_window(uuid) from public, anon;
grant  execute on function public.begin_challenge_window(uuid) to authenticated;

comment on function public.begin_challenge_window(uuid) is
  'Opens the owner-challenge window (Phase 11-E, rewritten 11-F, re-scoped 11-OC/D). Its ONLY legal '
  'input is owner_notification_dispatched — the death_verified -> challenge_window edge was deleted, '
  'so a window cannot open on an un-notified owner even by mistake. Phase D replaced the inert '
  'estate-scoped status <> cancelled predicate with the fact it needs: a committed email notice for '
  'the CURRENT case episode (no_current_notice otherwise). It deliberately does NOT require '
  'notice_accepted_at — opening the window discloses nothing and the initial notice is normally '
  'still queued. Admin-gated; idempotent; discloses nothing.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- authorize_release(p_estate, p_reason) → text                                 [admin, AAL2+fresh]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ THE TWO-PERSON RULE (D1), AND WHY IT LIVES IN THE DATABASE. The operator who verified the death
-- may not authorize the release. A console can enforce that and a console can be bypassed — by a
-- direct RPC, a future admin tool, a script, or the next rewrite. Here the rule is enforced twice on
-- purpose: this routine refuses, AND `release_authorizations` carries a CHECK constraint that makes
-- a single-reviewer row unwritable by ANY path. The routine is the door; the constraint is the wall.
--
-- ★ reviewer_a IS DERIVED, NEVER SUPPLIED. It is read from the verified case's `decided_by` — the
-- operator who actually made the call. A parameter would let the caller nominate a different
-- "first reviewer" and satisfy the rule against someone who never reviewed anything.
--
-- ★ THIS ROUTINE REPLACES 11-E's `release_estate`, WHICH IS DROPPED BY 0055. Leaving a one-person
-- lever beside a two-person door would be the whole decision undone by an un-rewired caller.
--
-- ★ AND IT STILL MANUFACTURES NOTHING (D5). No grant, no tier, no membership, no designation. The
-- lifecycle moves and the ONE canonical predicate answers differently for grants the owner already
-- authored.
--
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- ★ PHASE 11-OC / PHASE D — THE OWNER-NOTICE CUTOVER. WHAT CHANGED, AND WHAT DELIBERATELY DID NOT.
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- EXACTLY TWO defective semantics are replaced, and every other guard in this routine is preserved
-- verbatim. Phase D makes release STRICTLY HARDER on every path and easier on none.
--
--   REPLACED · the owner-notice precondition
--       was:  an email row on this ESTATE with `status <> 'cancelled'`
--       now:  `owner_notice_release_authority(v_case)` — the CURRENT generation of the CURRENT
--             episode carries `notice_accepted_at`
--
--   REPLACED · the release clock anchor
--       was:  `now() > owner_notified_at + duration`   (stamped when the row was QUEUED)
--       now:  `now() > notice_accepted_at + duration`  (stamped when the PROVIDER ACCEPTED it)
--
--   PRESERVED · admin gate · non-blank reason · idempotent `released` replay · lifecycle must be
--   `challenge_window` · `owner_notified_at`/`safety_notification_id` present (now PROVENANCE, and
--   kept precisely because Phase D must not make any path easier) · verified-case requirement ·
--   reviewer_a DERIVED from the case decider · reviewer_b distinct · the `release_authorizations`
--   CHECK constraint · live `challenge_window_duration()` · STRICT `>` · the audit row · the
--   transition to `released`.
--
-- ★ THE REFUSAL ORDER IS UNCHANGED FOR EVERY PRE-EXISTING SENTINEL. `invalid_release_state`,
-- `owner_not_notified`, `no_verified_case`, `reviewer_a_unresolved` and `two_person_rule_violated`
-- all still fire before any clock or notice question, in that order, so a caller that was refused
-- for one of those reasons before is refused for the same reason now. The acceptance authority
-- occupies exactly the position the old `owner_channel_unreachable` predicate held relative to the
-- clock: after the two-person rule, before the release is written.
--
-- ★ THE AUTHORITY IS CONSULTED, NEVER RESTATED. This routine contains no status list, no
-- `superseded_by` test, no `case_id` join and no clock arithmetic of its own — all four live in
-- `owner_notice_release_authority`, which the operator console reads through the SAME function. A
-- second copy here is how a door and a console come to disagree in front of an operator holding an
-- irreversible lever.
create or replace function public.authorize_release(p_estate uuid, p_reason text)
 returns text
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_row        public.estate_lifecycle%rowtype;
  v_uid        uuid;
  v_case       uuid;
  v_reviewer_a uuid;
  v_verified   timestamptz;
  v_duration   interval;
  v_auth       jsonb;
begin
  perform public.admin_require_gate();
  v_uid := auth.uid();

  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'audit_reason_required' using errcode = 'P0001';
  end if;

  select l.* into v_row
    from public.estate_lifecycle l
   where l.estate_id = p_estate
   for update;

  if v_row.state = 'released' then
    return 'released'; -- idempotent replay: no second authorization row, no re-audit
  end if;
  if v_row.state is distinct from 'challenge_window' then
    -- challenge_halted lands here too: release can NEVER proceed from a halted process.
    raise exception 'invalid_release_state' using errcode = 'P0001';
  end if;

  -- The dispatch facts (D4), KEPT IN PHASE D AS PROVENANCE. These no longer decide when a release
  -- may proceed — `owner_notice_release_authority` does — but removing them would make one path
  -- easier, and Phase D makes no path easier. A window whose lifecycle row cannot even name the
  -- dispatch that opened it cannot elapse into disclosure.
  if v_row.owner_notified_at is null or v_row.safety_notification_id is null then
    raise exception 'owner_not_notified' using errcode = 'P0001';
  end if;

  select c.id, c.decided_by, c.decided_at into v_case, v_reviewer_a, v_verified
    from public.death_verification_cases c
   where c.estate_id = p_estate and c.status = 'verified'
   order by c.decided_at desc
   limit 1;
  if v_case is null then
    raise exception 'no_verified_case' using errcode = 'P0001';
  end if;
  if v_reviewer_a is null then
    raise exception 'reviewer_a_unresolved' using errcode = 'P0001';
  end if;

  -- ★ D1, ENFORCED HERE AND AGAIN BY THE TABLE CONSTRAINT BELOW.
  if v_uid = v_reviewer_a then
    raise exception 'two_person_rule_violated' using errcode = 'P0001';
  end if;

  -- ════════════════════════════════════════════════════════════════════════════════════════════
  -- ★ PHASE D — THE OWNER-NOTICE ACCEPTANCE AUTHORITY AND THE RELEASE CLOCK, IN ONE CONSULTATION.
  -- ════════════════════════════════════════════════════════════════════════════════════════════
  --
  -- The verdict is read under the lifecycle row lock taken above, so the state it describes cannot
  -- move between the answer and the write. `owner_notice_release_authority` is `stable` — it reads
  -- the calling statement's snapshot — which is correct here for exactly that reason, and is the
  -- same contract `reissue_owner_safety_notice` has with `owner_notice_reissue_assessment`.
  --
  -- ★ THE REFUSAL CODE IS RAISED VERBATIM, NEVER TRANSLATED. A `case` expression mapping the
  -- authority's codes onto this routine's own sentinels would be a second policy: the console reads
  -- the authority directly, so a translation layer here is precisely how the two come to describe
  -- the same estate differently. `release_window_not_configured` and `release_window_not_elapsed`
  -- are therefore still the strings a caller sees — they are now the AUTHORITY's names for them.
  v_auth := public.owner_notice_release_authority(v_case);
  if not (v_auth ->> 'ready')::boolean then
    raise exception '%', v_auth ->> 'refusal_code' using errcode = 'P0001';
  end if;
  -- Read back for the audit, from the SAME verdict that authorized this release rather than from a
  -- second lookup that could describe a different row.
  v_duration := (v_auth ->> 'window_duration')::interval;

  insert into public.release_authorizations
    (estate_id, case_id, reviewer_a, reviewer_b, verified_at, authorized_at, released_at, audit_reason)
  values (p_estate, v_case, v_reviewer_a, v_uid, v_verified, now(), now(), p_reason);

  perform public.apply_estate_lifecycle_transition(
    p_estate, 'released', v_case, 'two_person_release');

  update public.estate_lifecycle
     set released_at = now()
   where estate_id = p_estate;

  insert into public.audit_logs (actor_id, estate_id, action, target_table, target_id, metadata, source)
  values (v_uid, p_estate, 'death_process.released', 'release_authorizations', v_case,
          jsonb_build_object('severity', 'high', 'case_id', v_case,
                            'reviewer_a', v_reviewer_a, 'reviewer_b', v_uid,
                            'verified_at', v_verified,
                            -- PROVENANCE, and labelled as such. It is no longer the clock, and an
                            -- investigator reconstructing a disputed release a year later must be
                            -- able to see which instant the seven days actually ran from.
                            'owner_notified_at', v_row.owner_notified_at,
                            -- ★ THE FACT THE RELEASE RESTED ON, and the two derived instants, taken
                            -- from the verdict that authorized it. Provider acceptance — never
                            -- delivery, and the key name says so.
                            'notice_accepted_at', v_auth ->> 'notice_accepted_at',
                            'release_eligible_at', v_auth ->> 'release_eligible_at',
                            'notice_id', v_auth ->> 'notice_id',
                            'notice_generation', v_auth ->> 'generation',
                            'window_duration', v_duration::text,
                            'audit_reason', p_reason),
          'admin');
  return 'released';
end $function$;
revoke execute on function public.authorize_release(uuid, text) from public, anon;
grant  execute on function public.authorize_release(uuid, text) to authenticated;

comment on function public.authorize_release(uuid, text) is
  'THE release transition (Phase 11-F, re-anchored 11-OC/D): challenge_window -> released, by a '
  'SECOND platform operator. Requires admin gate, a non-empty audit reason, the dispatch provenance '
  'on the lifecycle row, a verified case, reviewer_b <> reviewer_a where reviewer_a is DERIVED from '
  'the case decider, and — from Phase D — owner_notice_release_authority: the CURRENT generation of '
  'the CURRENT case episode must carry notice_accepted_at (PROVIDER ACCEPTANCE, never mailbox '
  'delivery) and the window must be STRICTLY elapsed from THAT instant, not from owner_notified_at. '
  'No status string participates. Ties go to the owner challenge. Records a release_authorizations '
  'row whose CHECK constraint makes a single-reviewer release unwritable by any path. Creates no '
  'grant, tier, membership or designation.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- challenge_death_process(p_estate) → text                          [the authenticated OWNER only]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ R13 IS THE SIGNATURE: one argument, one action. No evidence parameter exists, no review step
-- exists, no waiting period exists, no designation is consulted. The authenticated owner of the
-- estate halts the process — from pending, from death_verified, or from inside the window — and
-- challenge_halted is terminal in 11-E: the map has no edge out, and no routine reopens it.
--
-- ★ THE GATE RUNS BEFORE ANY EXISTENCE OR STATE LOOKUP. `is_estate_owner` answers false for a
-- nonexistent estate and a foreign one alike, so every unauthorized caller — beneficiary,
-- designee, claimant, foreign owner, probe against a random uuid — refuses with the same bytes.
create or replace function public.challenge_death_process(p_estate uuid)
 returns text
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid       uuid := auth.uid();
  v_state     text;
  -- ★ Phase 11-L. The initiator of the case THIS CALL halts, captured from the UPDATE's own
  -- RETURNING rather than looked up afterwards. A separate SELECT could name a case this call did
  -- not touch — one already halted, or one halted by a concurrent transaction — and would notify
  -- someone about a process that is still running, or notify twice about one that stopped once.
  v_initiator uuid;
begin
  if v_uid is null then
    raise exception 'auth_required' using errcode = '42501';
  end if;
  if not public.is_estate_owner(p_estate) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  select l.state into v_state
    from public.estate_lifecycle l
   where l.estate_id = p_estate
   for update;
  if v_state is null then
    v_state := 'active';
  end if;

  if v_state = 'challenge_halted' then
    return 'challenge_halted'; -- idempotent replay: no re-stamp, no re-audit
  end if;
  if v_state = 'active' then
    raise exception 'nothing_to_challenge' using errcode = 'P0001';
  end if;
  -- Too late is stated honestly (R15): what was disclosed cannot be undisclosed, and pretending
  -- a halt succeeded would claim otherwise. The owner is authorized to know this about their
  -- own estate.
  if v_state = 'released' then
    raise exception 'already_released' using errcode = 'P0001';
  end if;

  perform public.apply_estate_lifecycle_transition(
    p_estate, 'challenge_halted', null, 'owner_challenge');

  update public.estate_lifecycle
     set halted_at = now()
   where estate_id = p_estate;

  -- The live case is halted — distinct from 'cancelled' (initiator withdrew): the owner said no.
  --
  -- ★ PHASE 11-NR — THE SET IS ('open','verified'), AND 'open' ALONE WAS THE DEFECT. This predicate
  -- read `status = 'open'`, which is the case status at exactly ONE of the four lifecycle states this
  -- routine can be reached from. The Branch A production drill measured the consequence: on the
  -- canonical operator-driven path the estate reached challenge_halted while its case row stayed
  -- 'verified', `v_initiator` came back NULL, and the 11-L halt notification — the entire deliverable
  -- of that phase — was never emitted to anybody. The case also stayed in the operator's `verified`
  -- work queue, invisible to a `halted` filter, with the queue row stating the contradiction outright.
  --
  -- The set is CLOSED and derived from the transition map, never "every row for this estate":
  --
  --   death_verification_pending    → case is 'open'      (initiate)
  --   death_verified                → case is 'verified'  (admin_decide 'verify')
  --   owner_notification_dispatched → case is 'verified'  (dispatch requires a verified case)
  --   challenge_window              → case is 'verified'  (begin_challenge_window requires one)
  --
  -- 'rejected' and 'cancelled' both return the lifecycle to `active`, where this routine has already
  -- raised `nothing_to_challenge` — they are decided history and settling them would overwrite an
  -- adjudication that did happen. 'halted' is excluded as a SECOND, independent guard against a
  -- re-stamp: the idempotent return above already refuses to reach this statement.
  --
  -- ★ AND IT STILL MATCHES AT MOST ONE ROW, WHICH NO LONGER FOLLOWS FROM THE INDEX ALONE.
  -- `death_verification_cases_one_open_per_estate` makes 'open' unique per estate; 'verified' is
  -- unique per estate for a different reason, and it is the state machine that supplies it. A
  -- verified case pins the lifecycle at death_verified or beyond, `initiate_death_verification_case`
  -- refuses unless the lifecycle is `active`, and no edge returns there from death_verified — so a
  -- second case cannot be opened once one is verified, and an 'open' case cannot coexist with a
  -- 'verified' one. Historical 'rejected' / 'cancelled' rows DO coexist and are excluded by the
  -- predicate. `into` therefore still has no set to choose from arbitrarily, and
  -- `release_safety_authorization.sql` §8 proves it on an estate that actually carries a decided
  -- historical case beside the live one.
  --
  -- ★ RETURNING gives us the initiator of the case actually settled HERE. A separate SELECT could
  -- name a case this call did not touch — one already halted, one from a prior rejected attempt, or
  -- one halted by a concurrent transaction — and would notify the wrong person, or notify twice
  -- about a process that stopped once.
  update public.death_verification_cases
     set status = 'halted', updated_at = now()
   where estate_id = p_estate and status in ('open', 'verified')
  returning initiated_by into v_initiator;

  -- ────────────────────────────────────────────────────────────────────────────────────────────
  -- ★ PHASE 11-L — TELL THE INITIATING FIDUCIARY THAT THEIR PROCESS STOPPED.
  -- ────────────────────────────────────────────────────────────────────────────────────────────
  --
  -- ★ RECIPIENT COMES FROM WORKFLOW STATE, NEVER FROM A CALLER. `p_estate` is the only input to
  -- this routine; there is no recipient parameter and therefore nothing for a client to point at
  -- someone else. `initiated_by` is `not null references auth.users(id)` on the case row.
  --
  -- ★ HISTORICAL INITIATOR, AND THE CASE MODEL SETTLES IT RATHER THAN A GUESS. 0052 states that
  -- `initiator_designation_id` / `initiator_capacity` are "a snapshot of fact ('this person acted
  -- as executor'), never an authority the case can later re-assert — a revoked designee does not
  -- keep acting because a case remembers them." So a designation revoked after initiation must NOT
  -- suppress this message: the notification asserts no authority, it reports one fact about
  -- something the recipient personally did. They already know they initiated it; being told it
  -- stopped discloses nothing they did not bring with them. Re-deriving a LIVE designation here
  -- would instead silently drop the message for exactly the person owed it.
  --
  -- ★ IT CANNOT REACH THE OWNER. The owner is the caller (is_estate_owner above), and the guard
  -- below excludes them explicitly. That covers the degenerate case where an estate owner is also
  -- a designee on their own estate: they would otherwise receive claimant-facing copy about their
  -- own halt, which reads as a message from a stranger about their own death process.
  --
  -- ★ NO DEEP LINK, DELIBERATELY. The recipient's own surface is `/executor`
  -- (`get_executor_workspace`, which refuses a revoked designee) — but the RN deep-link allowlist
  -- in `features/notifications/actions.ts` has no `afterworth://executor` key, and a link that is
  -- not in the allowlist resolves to null and renders as a non-navigating row anyway. Passing an
  -- unmatched string would be inventing a route rather than using one. Wiring that destination is
  -- a bounded mobile follow-up, recorded in docs/phase11l-halt-notification.md §6.
  --
  -- ★ EMISSION IS INSIDE THIS TRANSACTION, so it commits with the halt or not at all — no
  -- notification can precede or outlive the state change it describes. The idempotent-replay
  -- return above happens BEFORE any of this, so a second challenge emits nothing. And when no case
  -- was open, `v_initiator` is null and nothing is emitted: a halt with no initiated process to
  -- report has nobody to report it to.
  if v_initiator is not null and v_initiator <> v_uid then
    perform public.emit_lifecycle_notification(
      v_initiator, p_estate, 'death_process.halted', null);
  end if;

  -- ★ NO PROVENANCE. The fact recorded is THAT the owner challenged and from which state — never
  -- a channel, a device, an address, or a location (§17: provenance is security-sensitive
  -- information about a living owner).
  perform public.write_audit(
    'death_process.challenged', 'estate_lifecycle', null, p_estate,
    jsonb_build_object('severity', 'high', 'from_state', v_state));
  return 'challenge_halted';
end $function$;
revoke execute on function public.challenge_death_process(uuid) from public, anon;
grant  execute on function public.challenge_death_process(uuid) to authenticated;

comment on function public.challenge_death_process(uuid) is
  'The owner challenge (Phase 11-E, R12-R14): the authenticated estate owner halts a pre-released '
  'death process in one action — no evidence, no review, no waiting, no designation. Wins ties '
  '(release requires the window strictly elapsed; both serialize on the lifecycle row lock). '
  'Produces challenge_halted, terminal in 11-E. Records no provenance beyond the act itself.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- release_estate — REMOVED IN PHASE 11-F. Its replacement is `authorize_release` above.
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ REMOVED FROM SOURCE, AND DROPPED BY MIGRATION 0055 — both halves are required. 11-E's
-- `release_estate(uuid)` released on ONE operator's say-so, which D1 forbids. Deleting only the
-- source would leave the function alive in every database that ever applied 11-E, because
-- `create or replace` cannot remove what it no longer mentions; dropping only in the migration
-- would let the next bundle paste recreate it from source. So the definition is gone from here and
-- the drop ships in the migration beside it — the 0053 precedent, applied to an actor rather than
-- to an argument.
--
-- A caller that was never rewired now fails loudly (`function does not exist`) instead of quietly
-- releasing an estate without a second reviewer.

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- get_owner_safety_status(p_estate) → text                          [authenticated, owner-gated]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- The owner-facing presentation of their own estate's safety state — a CLOSED four-value union,
-- deliberately coarser than the lifecycle: the owner surface needs "is there something to halt",
-- never the machine's internals. An owner is authorized to know this about their own estate; no
-- one else may ask (same byte-identical refusal discipline as the challenge).
--
--   none          nothing to challenge (no death process, or it concluded without release)
--   challengeable a death process is underway and the owner may halt it
--   halted        the owner (or a prior challenge) halted the process
--   released      the process completed; the owner arrived too late to halt (stated honestly)
create or replace function public.get_owner_safety_status(p_estate uuid)
 returns text
 language plpgsql
 security definer
 stable
 set search_path to 'public'
as $function$
declare
  v_uid   uuid := auth.uid();
  v_state text;
begin
  if v_uid is null then
    raise exception 'auth_required' using errcode = '42501';
  end if;
  if not public.is_estate_owner(p_estate) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  v_state := public.estate_lifecycle_state(p_estate);
  -- ★ THE 11-F STATE JOINS THE `challengeable` GROUP, and that is the safety-preserving mapping:
  -- an owner who has just received the email is squarely in the population this surface exists for.
  -- The union stays four values on purpose — the owner needs "can I stop this", never the machine's
  -- internals, and a client that could distinguish dispatched from windowed would be a client with
  -- something to branch on.
  return case v_state
    when 'death_verification_pending'    then 'challengeable'
    when 'death_verified'                then 'challengeable'
    when 'owner_notification_dispatched' then 'challengeable'
    when 'challenge_window'              then 'challengeable'
    when 'challenge_halted'              then 'halted'
    when 'released'                      then 'released'
    else 'none'
  end;
end $function$;
revoke execute on function public.get_owner_safety_status(uuid) from public, anon;
grant  execute on function public.get_owner_safety_status(uuid) to authenticated;

comment on function public.get_owner_safety_status(uuid) is
  'Owner-scoped safety status (Phase 11-E): a closed presentation union (none / challengeable / '
  'halted / released) over the authoritative lifecycle, for the challenge surface. Owner-only; '
  'every other caller refuses byte-identically. Not an authorization and not a disclosure: it '
  'answers about the process, never about estate content.';


-- ==== db/functions/operator_console.sql ===========================================================
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- PHASE 11-K · OPERATOR PROJECTIONS — the two READ doors that make nine deployed WRITE doors usable
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- ★ WHY THIS FILE EXISTS AT ALL. Phase 11 deployed nine admin-gated write routines and not one way
-- to see what they act on. `death_verification_cases`, `death_verification_evidence` and
-- `estate_lifecycle` were created with ZERO grants and ZERO policies (0052 asserts exactly that),
-- and no `admin_list_*`/`admin_get_*` routine was ever written for them. The consequence is sharper
-- than "unbound": an operator holding a valid AAL2 admin JWT can DECIDE a case, but has no way to
-- learn a case id, so there is nothing they can name. The lifecycle was unreachable by anyone.
--
-- ★ NOTHING HERE CREATES AUTHORITY. Both routines are STABLE reads behind the same
-- `admin_require_gate()` every other admin door uses — auth → is_admin → AAL2 → 15-minute freshness,
-- INSIDE the definer (the DEFINER-door discipline: a direct PostgREST caller hits the identical
-- checks, and the console buys no privilege the raw door does not already give). No lifecycle
-- moves, no level changes, no case is decided, no notice dispatches, no window opens, nothing
-- releases. Every one of those remains the deployed routine's own decision.
--
-- ★ AND THIS IS NOT AN ADMIN ESTATE DUMP. Administrative workflow authority and estate-content
-- disclosure are separate axes, and least disclosure applies to operators too. These projections
-- answer about the VERIFICATION WORKFLOW and carry, in neither routine:
--
--     no asset, no valuation, no net worth        no beneficiary, no membership roster
--     no designation list                          no access grant, no visibility tier
--     no document bytes, no storage path           no signed URL
--     no encrypted instruction                     NO OWNER EMAIL ADDRESS
--
-- The full field-by-field justification, with sensitivity and retention, is
-- `docs/phase11k-disclosure-census.md`. `test/operatorProjectionDisclosure.test.ts` pins the
-- absences against this source text with positive controls, so a future edit that adds one of them
-- fails rather than ships.
--
-- Source of truth — re-apply on DB reset. Deploys with `db/bundles/operator_console_bundle.sql`,
-- after migration 0056.

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- admin_list_death_verification_cases(...) → table                            [admin, AAL2+fresh]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- THE OPERATOR QUEUE. What an operator needs to triage a list of cases, and nothing else.
--
-- ★ NO OWNER EMAIL, AND `owner_channel_resolvable` INSTEAD. The operator's workflow question is
-- "will dispatch succeed for this estate", not "what is this living person's address". The boolean
-- answers the first exactly and the second not at all — and `dispatch_owner_safety_notice` resolves
-- the real address itself, from `auth.users`, where no claimant can repoint it. An operator never
-- needs to see it, so this projection never has it to leak. A console that displayed the address
-- "for confirmation" would be a permanent, searchable copy of a living owner's contact detail in a
-- surface whose whole premise is that this person may be the victim of a false claim.
--
-- ★ THE REQUIRED LEVEL IS RE-DERIVED LIVE, matching `admin_decide_death_verification_case` exactly.
-- `required_level_at_initiation` is a record of what policy said when the case opened; showing THAT
-- as the bar would mislead whenever policy tightened mid-case — and the decision routine would then
-- refuse a `verify` the console had just shown as permitted. The console must not be able to
-- disagree with the door.
--
-- ★ INITIATOR IDENTITY IS WITHHELD HERE and disclosed only in the case file, where adjudicating a
-- specific claim actually requires it. A queue needs to know a case exists; it does not need to
-- name the person who opened it.
create or replace function public.admin_list_death_verification_cases(
  p_status           text        default null,
  p_before_initiated timestamptz default null,
  p_before_id        uuid        default null,
  p_limit            int         default 50
)
 returns table(
   case_id                  uuid,
   estate_id                uuid,
   estate_name              text,
   case_status              text,
   lifecycle_state          text,
   event_type               text,
   initiated_at             timestamptz,
   updated_at               timestamptz,
   initiator_capacity       text,
   jurisdiction_context     text,
   required_level           text,
   attained_level           text,
   evidence_total           int,
   evidence_awaiting_review int,
   owner_channel_resolvable boolean,
   decided_at               timestamptz
 )
 language plpgsql
 security definer
 stable
 set search_path to 'public'
as $function$
declare v_limit int;
begin
  perform public.admin_require_gate();
  -- The admin_list_claim_packets_enriched clamp, verbatim: a caller cannot ask for the whole table.
  v_limit := least(greatest(coalesce(p_limit, 50), 1), 200);

  return query
    select
      c.id,
      c.estate_id,
      e.name,
      c.status,
      -- An estate with no lifecycle row has never entered the machine; `active` is the same default
      -- `apply_estate_lifecycle_transition` and `estate_lifecycle_state` both use.
      coalesce(l.state, 'active'),
      c.event_type,
      c.created_at,
      c.updated_at,
      c.initiator_capacity,
      c.jurisdiction_context,
      public.required_verification_level(c.estate_id)::text,
      c.attained_level::text,
      coalesce(ev.total, 0)::int,
      coalesce(ev.awaiting, 0)::int,
      exists (
        select 1 from auth.users u
         where u.id = public.estate_owner_user_id(c.estate_id)
           and btrim(coalesce(u.email, '')) <> ''
      ),
      c.decided_at
    from public.death_verification_cases c
    left join public.estates e on e.id = c.estate_id
    left join public.estate_lifecycle l on l.estate_id = c.estate_id
    left join lateral (
      -- ★ A LATERAL AGGREGATE, NOT A JOINED GROUP BY. The 11-F census learned this the expensive
      -- way: a per-status GROUP BY joined laterally onto the row set multiplies rows, and the
      -- headline number silently triples. Scoped to `x.case_id = c.id`, this returns one row.
      select count(*)::int as total,
             count(*) filter (where x.review_status = 'received')::int as awaiting
        from public.death_verification_evidence x
       where x.case_id = c.id
    ) ev on true
   where (p_status is null or c.status = p_status)
     and (p_before_initiated is null
          or (c.created_at, c.id) < (p_before_initiated, coalesce(p_before_id, c.id)))
   order by c.created_at desc, c.id desc
   limit v_limit;
end $function$;
revoke execute on function public.admin_list_death_verification_cases(text, timestamptz, uuid, int)
  from public, anon;
grant  execute on function public.admin_list_death_verification_cases(text, timestamptz, uuid, int)
  to authenticated;

comment on function public.admin_list_death_verification_cases(text, timestamptz, uuid, int) is
  'The operator queue for death-verification cases (Phase 11-K). Workflow facts only: case status, '
  'lifecycle state, LIVE required level vs attained, evidence counts, and whether the owner channel '
  'RESOLVES — never the owner address. No asset, valuation, beneficiary, designation, grant, '
  'document byte or storage path. Admin-gated inside the definer; keyset paged; clamped to 200.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- admin_get_death_verification_case(p_case) → jsonb                           [admin, AAL2+fresh]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- THE CASE FILE. Everything the six lifecycle decisions actually turn on, assembled in ONE call so
-- the console cannot compose a wider view out of several narrow ones — and so there is a single
-- place to audit what an operator may see.
--
-- ★ `viewer_is_reviewer_a` IS DERIVED FROM auth.uid() INSIDE THIS DEFINER. That is the whole reason
-- it lives here rather than in the client. The console must be able to state that the signed-in
-- operator is ineligible to authorize this release; a client that computed it by comparing two
-- values it was handed could be made to compute it wrongly, and the failure would be silent and in
-- the operator's favour. The server answers it, the client renders it, and `authorize_release`
-- re-derives reviewer_a and re-checks distinctness independently regardless. This field makes the
-- affordance TRUTHFUL; it grants nothing. UI affordance is not permission.
--
-- ★ WINDOW FACTS ARE FACTS, NOT A COUNTDOWN. `release_eligible_at` and `elapsed` are what an
-- operator needs in order to know whether a release call will be refused. Since Phase 11-OC / Phase
-- D they are not computed here at all: they are read from `owner_notice_release_authority`, the same
-- function `authorize_release` consults, so the console cannot display a deadline the routine
-- disagrees with — not because it copies the routine's arithmetic carefully, but because there is
-- only one piece of arithmetic. `elapsed` is STRICT `>` inside that authority for the reason the
-- routine needs it: at the exact boundary instant release refuses and the owner's challenge still
-- succeeds, and a console that rounded the other way would offer an action that is refused.
-- Nothing here ranks, scores, urges, estimates, or performs urgency.
--
-- ★ DECISION AND REVIEW NOTES ARE INCLUDED, AS A WORKFLOW REQUIREMENT RATHER THAN A CONVENIENCE.
-- The second reviewer must form an independent judgement about what the FIRST reviewer concluded; a
-- two-person rule where reviewer B cannot read reviewer A's reasoning is a rubber stamp with extra
-- steps. These are operator-authored notes about a case, never estate content.
--
-- ★ REFUSAL SHAPE DIFFERS FROM THE CLIENT DOORS, DELIBERATELY. The client routines answer one
-- sentinel for missing-and-foreign alike, because case existence is itself protected from a probing
-- claimant (T9). An authenticated platform admin behind AAL2 + freshness is authorized to know that
-- a case does not exist — the same latitude `admin_review_death_evidence` already takes with
-- `evidence_not_found`. Copying the client's indistinguishability here would hide operator typos,
-- not protect anyone.
create or replace function public.admin_get_death_verification_case(p_case uuid)
 returns jsonb
 language plpgsql
 security definer
 stable
 set search_path to 'public'
as $function$
declare
  v_uid      uuid;
  v_c        public.death_verification_cases%rowtype;
  v_l        public.estate_lifecycle%rowtype;
  v_duration interval;
  v_auth     jsonb;
  v_out      jsonb;
begin
  perform public.admin_require_gate();
  v_uid := auth.uid();

  select * into v_c from public.death_verification_cases c where c.id = p_case;
  if not found then
    raise exception 'case_not_found' using errcode = 'P0002';
  end if;

  select * into v_l from public.estate_lifecycle l where l.estate_id = v_c.estate_id;
  v_duration := public.challenge_window_duration();
  -- ★ PHASE D — ONE CONSULTATION, TWO CONSUMERS BELOW. Both `window` and `release_authority` read
  -- this single verdict, so the dates the console renders and the verdict it acts on can never
  -- describe different evaluations of the same estate.
  v_auth := public.owner_notice_release_authority(p_case);

  select jsonb_build_object(
    'case', jsonb_build_object(
      'case_id',              v_c.id,
      'estate_id',            v_c.estate_id,
      'estate_name',          (select e.name from public.estates e where e.id = v_c.estate_id),
      'status',               v_c.status,
      'event_type',           v_c.event_type,
      'initiated_at',         v_c.created_at,
      'updated_at',           v_c.updated_at,
      'initiator_capacity',   v_c.initiator_capacity,
      'jurisdiction_context', v_c.jurisdiction_context,
      -- BOTH levels, both labelled. The live value is the bar the decision routine will apply; the
      -- snapshot is the case file's record of what policy said at initiation. Showing only one of
      -- them is how a console and a decision routine come to disagree in front of an operator.
      'required_level_at_initiation', v_c.required_level_at_initiation::text,
      'required_level_live',  public.required_verification_level(v_c.estate_id)::text,
      'attained_level',       v_c.attained_level::text,
      'decided_at',           v_c.decided_at,
      'decision_note',        v_c.decision_note
    ),
    -- Initiator identity: disclosed HERE and not in the queue, because adjudicating THIS case is
    -- the workflow that needs it — an operator judging whether a claimed fiduciary is legitimate.
    'initiator', jsonb_build_object(
      'user_id',  v_c.initiated_by,
      'email',    (select p.email     from public.profiles p where p.id = v_c.initiated_by),
      'name',     (select p.full_name from public.profiles p where p.id = v_c.initiated_by),
      'capacity', v_c.initiator_capacity
    ),
    'lifecycle', jsonb_build_object(
      'state',                       coalesce(v_l.state, 'active'),
      'owner_notified_at',           v_l.owner_notified_at,
      'challenge_window_started_at', v_l.challenge_window_started_at,
      'halted_at',                   v_l.halted_at,
      'released_at',                 v_l.released_at,
      'updated_at',                  v_l.updated_at
    ),
    -- ────────────────────────────────────────────────────────────────────────────────────────
    -- ★ PHASE 11-OC / PHASE D — THE WINDOW FACTS COME FROM THE RELEASE AUTHORITY, NOT FROM HERE.
    -- ────────────────────────────────────────────────────────────────────────────────────────
    --
    -- This object used to compute its own clock: `owner_notified_at + duration`, and `elapsed` from
    -- the same anchor. That was a faithful mirror of the pre-Phase-D door — and being a faithful
    -- mirror is exactly the problem, because it was a SECOND implementation of the release clock.
    -- When Phase D re-anchored the door on `notice_accepted_at`, a console still computing from
    -- `owner_notified_at` would have shown an eligibility date up to several days too early and
    -- offered AUTHORIZE RELEASE on an estate the server refuses.
    --
    -- So both fields are now read from `owner_notice_release_authority` — the SAME function
    -- `authorize_release` consults — and this projection performs no clock arithmetic of its own.
    -- The `viewer_is_reviewer_a` discipline applied to a date: the server answers, the client
    -- renders, and the routine re-checks independently regardless.
    --
    -- ★ THE SHAPE IS PRESERVED so an older console keeps parsing. `duration`, `configured`,
    -- `release_eligible_at` and `elapsed` all still exist and still mean what their names say —
    -- they are simply now computed once, in the authority, from the acceptance fact.
    'window', jsonb_build_object(
      'duration',            v_duration::text,
      -- NULL duration means NOT CONFIGURED, which means the window never elapses and release
      -- refuses. The console must be able to say that, rather than render a blank date.
      'configured',          v_duration is not null,
      -- NULL until there is an acceptance fact to anchor on. A console must render that as "not yet
      -- eligible", never as a blank it fills in from provenance.
      'release_eligible_at', v_auth -> 'release_eligible_at',
      'elapsed',             coalesce((v_auth ->> 'elapsed')::boolean, false)
    ),
    -- ────────────────────────────────────────────────────────────────────────────────────────
    -- ★ PHASE 11-OC / PHASE D — RELEASE AUTHORITY IS THE SERVER'S ANSWER, NOT THE CLIENT'S GUESS.
    -- ────────────────────────────────────────────────────────────────────────────────────────
    --
    -- The console must offer AUTHORIZE RELEASE exactly when `authorize_release` would accept it on
    -- owner-notice grounds. That rule is not a status list: it turns on the CURRENT case episode, on
    -- the CURRENT generation, on the acceptance FACT rather than the status, and on a strict clock
    -- anchored to that fact. A TypeScript mirror of it would be a second policy governing an
    -- IRREVERSIBLE act — the highest-stakes place in this product for a console and a door to drift.
    --
    -- It carries a NAMED refusal code rather than a sentence, so the console owns the operator copy
    -- and the server owns the policy. No address, no owner identity, on any branch.
    --
    -- ★ IT IS NOT A PERMISSION. The two-person rule, the admin gate, the lifecycle state and the
    -- audit reason are all re-checked inside `authorize_release` every single time. This field makes
    -- the affordance TRUTHFUL; it grants nothing.
    'release_authority', v_auth,
    -- ────────────────────────────────────────────────────────────────────────────────────────
    -- ★ PHASE 11-OC — THE EPISODE, NOT JUST A LIST OF ROWS.
    -- ────────────────────────────────────────────────────────────────────────────────────────
    --
    -- Phase A gave a notice an episode (`case_id`), a position in it (`generation`), a retirement
    -- link (`superseded_by`) and the one fact release turns on (`notice_accepted_at`). Without those
    -- four the console can render only a status — and a status is precisely what this phase proved is
    -- not enough: `dispatched` means "provider accepted" for a row written after Phase A and means
    -- "we do not know" for a row written before it. A console that labelled both the same way would
    -- state, on the one screen where it matters, that a living owner was reached when nobody knows.
    --
    -- `is_current` is projected rather than left to the client to derive from `superseded_by`,
    -- because a retired generation and a live one must never be shown with the same weight, and a
    -- null-check is exactly the kind of derivation a UI gets wrong once and then keeps.
    --
    -- ★ STILL NO ADDRESS. `recipient` is NOT selected, here or anywhere in this file. An operator's
    -- workflow never requires a living owner's address, and a projection that never carries it cannot
    -- leak it through a log, a screenshot, or a future console feature. Every field added here is a
    -- workflow fact about a queue row; none of them is contact detail.
    'owner_notice', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id',            o.id,
               'channel',       o.channel,
               'notice_kind',   o.notice_kind,
               'status',        o.status,
               'requested_at',  o.requested_at,
               'dispatched_at', o.dispatched_at,
               'attempts',      o.attempts,
               'failure_class', o.failure_class,
               -- The episode this row belongs to. NULL on a pre-Phase-A row, which is the honest
               -- answer: those belong to no provable episode and are never guessed into one.
               'case_id',            o.case_id,
               'generation',         o.generation,
               'superseded_by',      o.superseded_by,
               'is_current',         o.superseded_by is null,
               -- THE FACT. NULL is a real answer and the console must render it as one.
               'notice_accepted_at', o.notice_accepted_at,
               'claimed_at',         o.claimed_at
             ) order by o.requested_at desc)
        from public.owner_notice_outbox o
       where o.estate_id = v_c.estate_id
    ), '[]'::jsonb),
    -- ────────────────────────────────────────────────────────────────────────────────────────
    -- ★ PHASE 11-OC / PHASE C — ACTION AVAILABILITY IS THE SERVER'S ANSWER, NOT THE CLIENT'S GUESS.
    -- ────────────────────────────────────────────────────────────────────────────────────────
    --
    -- The console must offer "Re-send owner safety notice" exactly when
    -- `reissue_owner_safety_notice` would accept it. The eligibility rule is not a status list — it
    -- turns on the lifecycle state, on whether this case is still the CURRENT episode, on the
    -- acceptance FACT (not the status), and on whether an address resolves. A TypeScript mirror of
    -- that would be a second policy, and the first time the two drifted an operator would either be
    -- offered a control the door refuses or denied one an estate needs.
    --
    -- So the verdict comes from `owner_notice_reissue_assessment`, the SAME function the door
    -- consults, and the console renders it. This is the `viewer_is_reviewer_a` discipline applied to
    -- an action: the server answers, the client displays, and the routine re-checks independently
    -- regardless. UI affordance is not permission — this grants nothing.
    --
    -- It carries a NAMED refusal code rather than a sentence, so the console owns the operator copy
    -- and the server owns the policy. Counts and codes only; no address on any branch.
    'owner_notice_reissue', public.owner_notice_reissue_assessment(v_c.id),
    'evidence', coalesce((
      select jsonb_agg(jsonb_build_object(
               'evidence_id',   x.id,
               'document_id',   x.document_id,
               'title',         d.title,
               'doc_type',      d.doc_type,
               'uploaded_at',   d.created_at,
               'submitted_at',  x.submitted_at,
               'review_status', x.review_status,
               'reviewed_at',   x.reviewed_at,
               'review_note',   x.review_note
               -- No storage_path, no bytes, no signed URL. Evidence BYTES have their own separately
               -- gated door (the admin_authorize_claim_evidence pattern); metadata is what a review
               -- queue needs, and the two must not be conflated into one projection.
             ) order by x.submitted_at)
        from public.death_verification_evidence x
        left join public.documents d on d.id = x.document_id
       where x.case_id = v_c.id
    ), '[]'::jsonb),
    'release', jsonb_build_object(
      -- reviewer_a is the case DECIDER, derived exactly as authorize_release derives it. NULL until
      -- the case is decided — there is no first reviewer before there is a decision.
      'reviewer_a',           v_c.decided_by,
      'viewer_is_reviewer_a', v_c.decided_by is not null and v_c.decided_by = v_uid,
      'authorized', (
        select jsonb_build_object('authorized_at', ra.authorized_at,
                                  'reviewer_a',    ra.reviewer_a,
                                  'reviewer_b',    ra.reviewer_b,
                                  'audit_reason',  ra.audit_reason)
          from public.release_authorizations ra
         where ra.estate_id = v_c.estate_id
         order by ra.authorized_at desc
         limit 1
      )
    )
  ) into v_out;

  return v_out;
end $function$;
revoke execute on function public.admin_get_death_verification_case(uuid) from public, anon;
grant  execute on function public.admin_get_death_verification_case(uuid) to authenticated;

comment on function public.admin_get_death_verification_case(uuid) is
  'The operator case file (Phase 11-K): case facts, initiator identity, lifecycle timestamps, LIVE '
  'window facts, owner-notice dispatch status (NEVER the recipient address) and evidence METADATA. '
  'viewer_is_reviewer_a is derived from auth.uid() INSIDE this definer so the console can state '
  'release ineligibility truthfully — it grants nothing; authorize_release re-checks independently. '
  'Phase 11-OC/D: `window` and `release_authority` both come from owner_notice_release_authority, '
  'the SAME verdict the release door consults, so the console performs no notice qualification, no '
  'episode matching and no clock arithmetic of its own. Carries no asset, valuation, beneficiary, '
  'designation, grant, document byte or storage path.';


-- ==== db/migrations/0060_20260817_owner_notice_release_authority.sql ==============================
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- PHASE 11-OC · PHASE D — THE RELEASE DOOR IS RE-ANCHORED ON PROVIDER ACCEPTANCE
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- ★ THIS IS THE ARTIFACT THAT CHANGES WHEN A RELEASE MAY PROCEED, AND IT IS THE ONLY ONE.
-- Migrations 0056, 0057, 0058 and 0059 each assert, about themselves, that they did NOT make this
-- change. This one makes it, and every one of those guards is amended in the same commit to ask a
-- better question — "is the door's posture consistent with the migrations actually applied" —
-- rather than to pin a literal that is now gone by design. See §5 for the full R13 disposition.
--
-- ★ WHAT THE DEFECT WAS, STATED SO THIS FILE IS SELF-EXPLAINING.
--
-- `authorize_release` gated on an owner-notice row for the ESTATE with `status <> 'cancelled'`.
-- Nothing in production ever writes `'cancelled'` — one test fixture does, by direct UPDATE — so the
-- predicate reduced to "a row exists", which is exactly what `dispatch_owner_safety_notice`
-- guaranteed by inserting it in the same transaction. The gate re-asserted its own precondition and
-- admitted `queued` (never sent), `processing` (never settled), `outcomeUncertain` (unknown) and
-- `failedPermanent` (definitively failed). Separately, the seven-day clock ran from
-- `owner_notified_at`, stamped when the row was QUEUED — so the window elapsed while the message sat
-- unsent, and kept elapsing after the provider rejected it outright.
--
-- ★ WHAT REPLACES IT — ONE FACT, FOUR AUTHORITIES, ZERO STATUS STRINGS.
--
--        THE CURRENT GENERATION OF THE CURRENT CASE EPISODE HAS `notice_accepted_at`,
--        AND now() > THAT INSTANT + challenge_window_duration(), STRICTLY.
--
--   EPISODE     the notice belongs to the CURRENT death-verification case (D3)
--   GENERATION  it is the row nothing supersedes — `superseded_by is null`, never a max() (D4)
--   ACCEPTANCE  `notice_accepted_at is not null` — no status participates (D1/D2)
--   CLOCK       strict `>` from the acceptance instant, never from provenance (D5)
--
-- ★ PROVIDER ACCEPTED IS NOT MAILBOX DELIVERED, AND NOTHING DOWNSTREAM MAY RENAME IT.
-- `notice_accepted_at` records that the email provider ACCEPTED the message for delivery. It is not
-- delivered, received, opened or read. Phase D protects on the strongest persisted provider fact
-- this system currently has; it does not claim delivery attestation, and no console label, audit
-- field or document may say otherwise.
--
-- ★ THE SEVEN-DAY POLICY IS UNCHANGED. `challenge_window_duration()` is not touched by this
-- migration, and must not be. Only the instant the seven days count FROM has moved.
--
-- ★ THIS MIGRATION CONTAINS NO DDL, AND THAT IS DELIBERATE RATHER THAN AN OMISSION. Phase A (0058)
-- added every column this phase needs and Phase C (0059) added the episode wall; Phase D changes
-- only FUNCTION BODIES, which live in `db/functions/` and are pasted by the bundle. So this file is
-- the ASSERTION and SUPERSESSION artifact: it proves the cutover took, proves it took completely
-- rather than halfway, proves the authority behaves correctly BY EXECUTION, and reports the
-- population it now refuses. A migration that only asserts is still a migration — it fails the
-- transaction when the claim is false, which is the entire job.
--
-- ★ APPLY ORDER IS INVERTED RELATIVE TO EVERY EARLIER PHASE, AND THE BUNDLE ENFORCES IT.
-- 0058 and 0059 are pasted BEFORE the function files they accompany, because they widen constraints
-- those functions then rely on. This one is pasted AFTER `release_safety.sql` and
-- `operator_console.sql`, because every assertion below inspects the bodies those files install. A
-- migration cannot assert a cutover that has not been pasted yet.
--
-- Deploys via `db/bundles/owner_notice_release_authority_bundle.sql`. Source of truth — re-apply on
-- reset. IDEMPOTENT: it contains no DDL, so re-applying it re-runs the proofs and nothing else.

-- [psql meta-command removed for the SQL editor] \set ON_ERROR_STOP on

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 1 · THE AUTHORITY EXISTS, WITH THE PROPERTIES ITS CALLERS DEPEND ON
-- ────────────────────────────────────────────────────────────────────────────────────────────────
do $$
declare
  v_def  text;
  v_prov boolean;
  v_vol  char;
begin
  if to_regprocedure('public.owner_notice_release_authority(uuid)') is null then
    raise exception '0060 FAILED: public.owner_notice_release_authority(uuid) is absent. The Phase D '
      'migration is being applied without the function it exists to certify — the bundle part order '
      'is wrong, or release_safety.sql was not pasted.';
  end if;

  select p.prosecdef, p.provolatile into v_prov, v_vol
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'owner_notice_release_authority';

  -- SECURITY DEFINER: it reads owner_notice_outbox and death_verification_cases, neither of which
  -- carries a client grant. An INVOKER function here would return nothing to its gated callers.
  if not v_prov then
    raise exception '0060 FAILED: owner_notice_release_authority is not SECURITY DEFINER';
  end if;
  -- STABLE, not VOLATILE: the door reads it under a row lock and relies on snapshot semantics; a
  -- VOLATILE body would also be free to write, which an authority must never be.
  if v_vol <> 's' then
    raise exception '0060 FAILED: owner_notice_release_authority must be STABLE (provolatile=%)', v_vol;
  end if;

  -- ★ INTERNAL. No client role may reach the authority directly. Its callers are gated; it is not.
  if has_function_privilege('anon', 'public.owner_notice_release_authority(uuid)', 'execute')
     or has_function_privilege('authenticated', 'public.owner_notice_release_authority(uuid)', 'execute')
  then
    raise exception '0060 FAILED: a client role can execute owner_notice_release_authority — the '
      'release authority is reachable without passing a gated door';
  end if;

  raise notice '0060 · owner_notice_release_authority present, SECURITY DEFINER, STABLE, INTERNAL';
end $$;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 2 · THE THREE CONSUMERS CARRY THE NEW CONTRACT, AND NONE CARRIES THE OLD ONE
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ TEXT IS NOT THE ONLY VOTER HERE — §4 proves the behaviour by execution. What text can prove,
-- and behaviour cannot easily, is that a SECOND policy has not been left behind beside the first.
-- These assertions exist to make a half-cutover impossible, not to stand in for runtime evidence.
do $$
declare
  v_def   text;
  v_probe text;
begin
  -- ════════════════════════════════════════════════════════════════════════════════════════════
  -- ★ EVERY MATCH BELOW RUNS AGAINST prosrc WITH `--` COMMENTS STRIPPED, AND THAT IS LOAD-BEARING
  --   IN BOTH DIRECTIONS. IT WAS FOUND BY EXECUTION, NOT BY REVIEW.
  -- ════════════════════════════════════════════════════════════════════════════════════════════
  --
  -- Postgres stores a plpgsql function's body VERBATIM, comments included. On the first replay of
  -- this migration the check below raised
  --
  --     0060 FAILED: begin_challenge_window requires notice_accepted_at
  --
  -- against a body that does not require it and never did. The routine's own comment explains that
  -- it deliberately does NOT gate on acceptance — and naming the term was enough to fail an absence
  -- test. The same trap fired on `authorize_release`, whose Phase D banner quotes the superseded
  -- predicate in order to say it is gone.
  --
  -- This is the exact failure the repository has shipped five times in the other direction: a
  -- documentation string counted as evidence. Here it counted as debt. Both are the same mistake.
  --
  -- ★ STRIPPING COMMENTS ALSO CLOSES THE ATTACK THE R13 DESIGN COULD ONLY FORBID. `docs/` records
  -- "plant the literal in a comment" as the worst available R13 fix, refused because prosrc includes
  -- comments and the guards would then match prose. After this, they cannot: a comment containing
  -- `status <> 'cancelled'` no longer satisfies anything. The rule moves from a promise to a wall.
  --
  -- ★ STRING LITERALS ARE DELIBERATELY **NOT** STRIPPED. The evidence class these matchers exist to
  -- find lives inside quoted SQL — `status <> 'cancelled'` IS a string literal in the predicate, and
  -- every refusal sentinel is a literal in a `raise`. Stripping them would erase exactly what is
  -- being looked for. Comments must go; strings must stay. The two views are different tools.
  --
  -- ★ AND THE PREPROCESSING CARRIES ITS OWN POSITIVE CONTROL. A stripper that removed everything
  -- would satisfy every absence assertion below and read as a clean cutover.
  v_probe := regexp_replace(
    'x := 1; -- status <> ''cancelled'' lives in this comment' || chr(10) ||
    'raise exception ''keep_me'';',
    E'--[^\n]*', '', 'g');
  if v_probe like '%status <> ''cancelled''%' then
    raise exception '0060 FAILED [preprocessing control]: the comment stripper left commented text '
      'behind, so every absence assertion below can be satisfied by prose';
  end if;
  if v_probe not like '%raise exception ''keep_me''%' then
    raise exception '0060 FAILED [preprocessing control]: the comment stripper removed a CODE string '
      'literal. It would erase the evidence class these matchers exist to find, and every absence '
      'assertion below would pass vacuously.';
  end if;

  -- ── 2.1 the release door ────────────────────────────────────────────────────────────────────
  select prosrc into v_def from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'authorize_release';
  if v_def is null then
    raise exception '0060 FAILED: authorize_release does not exist';
  end if;
  v_def := regexp_replace(v_def, E'--[^\n]*', '', 'g');
  -- Per-site non-vacuity: the stripped body must still be recognisable CODE. A body reduced to
  -- nothing would satisfy every `not like` below.
  if v_def not like '%raise exception%' or v_def not like '%public.apply_estate_lifecycle_transition%' then
    raise exception '0060 FAILED: the stripped authorize_release body contains no recognisable code '
      '— the preprocessing has eaten the routine and every assertion below is vacuous';
  end if;
  if v_def not like '%public.owner_notice_release_authority(%' then
    raise exception '0060 FAILED: authorize_release does not consume the release authority';
  end if;
  -- The superseded predicate must be GONE, not merely joined by a newer one.
  if v_def like '%status <> ''cancelled''%' then
    raise exception '0060 FAILED: authorize_release still carries the OB-1 predicate '
      '(status <> cancelled) beside the Phase D authority — a half-applied cutover leaves two '
      'owner-notice policies in one routine';
  end if;
  -- ★ THE CLOCK IS NO LONGER ANCHORED ON PROVENANCE. `owner_notified_at` may still be READ (it is
  -- kept as a required dispatch fact and recorded in the audit), but it must not appear in an
  -- interval comparison — that is the defective clock, and its absence is the cutover.
  if v_def ~ 'owner_notified_at\s*\+' then
    raise exception '0060 FAILED: authorize_release still computes a deadline from owner_notified_at '
      '— the release clock has not been re-anchored on the acceptance fact';
  end if;
  -- STRICT `>` survives the move. At the exact boundary the owner challenge wins (R14).
  if v_def like '%>=%' and v_def not like '%v_row.attempts >=%' then
    raise exception '0060 FAILED: authorize_release contains a non-strict comparison — the boundary '
      'instant must go to the owner challenge, never to release';
  end if;
  -- Two-person rule and audit reason are UNTOUCHED by Phase D. Phase D adds authority; it replaces
  -- no existing release guard.
  if v_def not like '%two_person_rule_violated%' or v_def not like '%audit_reason_required%'
     or v_def not like '%owner_not_notified%' or v_def not like '%no_verified_case%'
     or v_def not like '%invalid_release_state%' then
    raise exception '0060 FAILED: authorize_release lost a pre-Phase-D guard. Phase D ADDS owner '
      'notice authority; it replaces no existing release guard.';
  end if;

  -- ── 2.2 the window door — corrected, and deliberately NOT tightened to acceptance (D7) ──────
  select prosrc into v_def from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'begin_challenge_window';
  if v_def is null then
    raise exception '0060 FAILED: begin_challenge_window does not exist';
  end if;
  v_def := regexp_replace(v_def, E'--[^\n]*', '', 'g');
  if v_def not like '%raise exception%' then
    raise exception '0060 FAILED: the stripped begin_challenge_window body contains no code';
  end if;
  if v_def like '%status <> ''cancelled''%' then
    raise exception '0060 FAILED: begin_challenge_window still carries the inert OB-1 predicate';
  end if;
  if v_def not like '%o.case_id = v_case%' then
    raise exception '0060 FAILED: begin_challenge_window does not scope its notice check to the '
      'resolved case — an accepted notice from a PRIOR death process could open a new window';
  end if;
  -- ★ THE LOAD-BEARING ABSENCE. Opening the window releases nothing, and the initial notice is
  -- normally still `queued` at this instant. Requiring acceptance here would make the window
  -- unopenable until a worker had run, and would gate the OWNER'S OWN PROTECTION on an email
  -- provider — the exact inversion where the protective act becomes harder than the harmful one.
  if v_def like '%notice_accepted_at%' then
    raise exception '0060 FAILED: begin_challenge_window requires notice_accepted_at. Phase D '
      'tightens the IRREVERSIBLE door only; gating the owner-challenge window on a provider makes '
      'the protective act harder than the harmful one.';
  end if;

  -- ── 2.3 the operator projection — the SAME authority, no second opinion ─────────────────────
  select prosrc into v_def from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'admin_get_death_verification_case';
  if v_def is null then
    raise exception '0060 FAILED: admin_get_death_verification_case does not exist';
  end if;
  v_def := regexp_replace(v_def, E'--[^\n]*', '', 'g');
  if v_def not like '%jsonb_build_object%' then
    raise exception '0060 FAILED: the stripped case-file body contains no code';
  end if;
  if v_def not like '%public.owner_notice_release_authority(%' then
    raise exception '0060 FAILED: the operator case file does not consume the release authority — '
      'the console would compute its own eligibility and could offer a release the door refuses';
  end if;
  if v_def ~ 'owner_notified_at\s*\+' then
    raise exception '0060 FAILED: the operator case file still computes a release deadline from '
      'owner_notified_at — the console and the door would disagree about the same estate';
  end if;

  -- ── 2.4 PHASE C IS STILL DEPLOYED AND STILL GATED — the remedy must outlive the cutover ─────
  --
  -- Phase D creates new legitimate refusal states that a running system reaches on its own. Without
  -- the re-notice remedy, the first post-cutover provider failure produces a permanently
  -- unreleasable estate whose only recovery is hand-written SQL against a safety table.
  if to_regprocedure('public.reissue_owner_safety_notice(uuid, text)') is null
     or to_regprocedure('public.owner_notice_reissue_assessment(uuid)') is null then
    raise exception '0060 FAILED: the Phase C re-notice remedy is not deployed. Phase D must not '
      'activate without it — the first provider failure after cutover would be unrecoverable.';
  end if;
  if has_function_privilege('anon', 'public.reissue_owner_safety_notice(uuid, text)', 'execute') then
    raise exception '0060 FAILED: anon can execute the re-notice door';
  end if;

  -- ── 2.5 THE ONE-PERSON LEVER IS STILL GONE, AND THE LOCKDOWN STILL HOLDS ────────────────────
  if to_regprocedure('public.release_estate(uuid)') is not null then
    raise exception '0060 FAILED: release_estate has been resurrected — a one-operator release lever '
      'beside a two-person door is the whole decision undone by an un-rewired caller';
  end if;
  if exists (
    select 1 from information_schema.role_table_grants
     where table_schema = 'public' and table_name = 'estate_release_state'
       and grantee in ('anon', 'authenticated')
  ) then
    raise exception '0060 FAILED: estate_release_state carries a client grant — the lockdown has '
      'been reversed underneath the release cutover';
  end if;

  raise notice '0060 · door consumes the authority, old predicate absent, clock re-anchored, window '
    'door episode-scoped WITHOUT acceptance, projection shares the authority, Phase C remedy '
    'deployed and gated, release_estate absent, estate_release_state locked';
end $$;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 3 · THE TWO-PERSON WALL IS UNTOUCHED
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- Asserted separately, and on the CONSTRAINT rather than on the routine, because the routine is the
-- door and the constraint is the wall. Phase D rewrote the door; if it had disturbed the wall, a
-- single-reviewer release would become writable by a path that never reads `authorize_release`.
do $$
declare v_def text;
begin
  select pg_get_constraintdef(oid) into v_def
    from pg_constraint where conname = 'release_authorizations_two_person_check';
  if v_def is null then
    -- Resolved from the catalog rather than guessed (the 0051 lesson): find ANY check on the table
    -- that mentions both reviewers, so a rename does not read as a deletion.
    select pg_get_constraintdef(con.oid) into v_def
      from pg_constraint con
      join pg_class rel on rel.oid = con.conrelid
      join pg_namespace nsp on nsp.oid = rel.relnamespace
     where nsp.nspname = 'public' and rel.relname = 'release_authorizations'
       and con.contype = 'c'
       and pg_get_constraintdef(con.oid) like '%reviewer_a%'
       and pg_get_constraintdef(con.oid) like '%reviewer_b%'
     limit 1;
  end if;
  if v_def is null then
    raise exception '0060 FAILED: release_authorizations carries no CHECK relating reviewer_a to '
      'reviewer_b — the two-person rule is now enforced only by a routine, and a routine can be '
      'bypassed by a direct RPC, a future admin tool, a script, or the next rewrite';
  end if;
  raise notice '0060 · the two-person CHECK constraint survives the cutover: %', v_def;
end $$;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 4 · THE AUTHORITY IS PROVEN BY EXECUTION — READ-ONLY, AGAINST WHATEVER THIS DATABASE HOLDS
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ WHY BEHAVIOURAL AT ALL. Every assertion in §2 reads `prosrc`, and `prosrc` includes comments. A
-- body could name the authority in prose and consult nothing; a body could consult it and misread
-- the verdict. So the load-bearing claims are EXECUTED on the same database and in the same
-- transaction as the deployment.
--
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- ★ THIS BLOCK WROTE A SYNTHETIC FIXTURE ONCE, AND IT FAILED THE FIRST PRODUCTION PASTE.
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- The original §4 created two `auth.users`, an estate, two cases, a lifecycle row and three owner
-- notices inside a subtransaction that always rolled back. It passed every local replay and aborted
-- production immediately:
--
--     0060 FAILED: the behavioural self-check could not run:
--     null value in column "id" of relation "users" violates not-null constraint (23502)
--
-- `insert into auth.users default values` works ONLY against the test harness, whose
-- `preamble_real_auth.sql` defines a simplified `auth.users` with `id uuid default gen_random_uuid()`.
-- Real Supabase has NO default there — GoTrue supplies the id. The self-check had therefore only
-- ever been exercised against a FAKE boundary, which is this repository's own recorded failure class:
-- a default that is never executed by any test, and a runtime that the local harness does not model.
--
-- ★ AND THE FAIL-CLOSED DESIGN HELD, which is the one good thing to record about it. The artifact is
-- a single transaction, so the abort deployed nothing, applied no half-cutover, and left no
-- synthetic row anywhere. A migration that had "helpfully" continued past a failed self-check would
-- have shipped an uncertified cutover instead.
--
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- ★ THE REPLACEMENT WRITES NOTHING, AND IS STRONGER EVIDENCE RATHER THAN WEAKER.
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- A production migration has no business creating estates, cases or owner notices in safety tables —
-- not even transiently, and not even attached to a real person's account, which is what reusing an
-- existing `auth.users` row would have required. So this block now proves the authority by RUNNING
-- it, with zero writes, in two ways:
--
--   · FAIL-CLOSED PROBES on inputs that need no fixture at all (§4.1);
--   · THE INVARIANTS, EVALUATED OVER EVERY CASE THIS DATABASE ACTUALLY HOLDS (§4.2-§4.4) — real
--     production rows, which no synthetic fixture can imitate.
--
-- ★ THE EXHAUSTIVE A-J MATRIX LIVES WHERE IT CAN BE BUILT SAFELY, AND THAT IS NOT HERE.
-- `db/tests/release_safety_authorization.sql` §12.1-§12.11 constructs interleaved episodes,
-- superseded generations carrying acceptance, prior rejected cases, exact clock boundaries and the
-- two-person matrix — against an ephemeral Postgres where fabricating an `auth.users` row is
-- legitimate. It runs on every replay and gates every PR. Build type follows evidence type: paste
-- time gets the evidence a paste can safely produce, and the suite gets the rest.
do $$
declare
  v_probe    jsonb;
  v_cases    bigint;
  v_bad      bigint;
  v_dur      interval;
begin
  -- ── 4.1 THE AUTHORITY EXECUTES, AND FAILS CLOSED ON INPUTS THAT NEED NO FIXTURE ─────────────
  --
  -- ★ THIS IS A REAL CALL, NOT A CATALOG LOOKUP. If the body were syntactically present but broken —
  -- a bad column reference, a missing helper, a wrong signature on `owner_notice_episode_kinds()` —
  -- it would raise here rather than pass a text match.
  v_probe := public.owner_notice_release_authority(null);
  if coalesce((v_probe ->> 'ready')::boolean, true) then
    raise exception '0060 FAILED [4.1]: the authority returned ready for a NULL case (%)', v_probe;
  end if;
  if v_probe ->> 'refusal_code' is distinct from 'case_not_found' then
    raise exception '0060 FAILED [4.1]: a NULL case produced refusal_code %, expected case_not_found',
      v_probe ->> 'refusal_code';
  end if;

  -- An id that certainly names no case. Fail closed, by name, rather than by crashing.
  v_probe := public.owner_notice_release_authority('00000000-0000-4000-8000-000000000000'::uuid);
  if coalesce((v_probe ->> 'ready')::boolean, true) then
    raise exception '0060 FAILED [4.1]: the authority returned ready for an unknown case (%)', v_probe;
  end if;
  if v_probe ->> 'refusal_code' is distinct from 'case_not_found' then
    raise exception '0060 FAILED [4.1]: an unknown case produced refusal_code %, expected '
      'case_not_found', v_probe ->> 'refusal_code';
  end if;
  raise notice '0060 · 4.1 the authority EXECUTES and fails closed on null and unknown cases';

  -- ── 4.2 NO CASE IS READY WITHOUT AN ACCEPTANCE FACT — over every real case ──────────────────
  --
  -- ★ THE CENTRAL PHASE D CLAIM, EVALUATED AGAINST PRODUCTION DATA RATHER THAN A FIXTURE. If any
  -- case in this database reports `ready` while `accepted` is false, the acceptance authority is not
  -- what is deciding releases and the cutover must not commit.
  select count(*) into v_cases from public.death_verification_cases;
  select count(*) into v_bad
    from public.death_verification_cases c
   where (public.owner_notice_release_authority(c.id) ->> 'ready')::boolean
     and not coalesce((public.owner_notice_release_authority(c.id) ->> 'accepted')::boolean, false);
  if v_bad > 0 then
    raise exception '0060 FAILED [4.2]: % case(s) report READY with no acceptance fact — the '
      'authority is not gating on notice_accepted_at', v_bad;
  end if;

  -- ── 4.3 THE ANCHOR IS THE ACCEPTANCE FACT, ARITHMETICALLY — over every real case ────────────
  --
  -- `release_eligible_at` must be NULL exactly when there is no acceptance fact, and must equal
  -- acceptance + the configured window whenever there is one. A body still anchored on
  -- `owner_notified_at` produces a NON-NULL date on every dispatched case with no acceptance, which
  -- is precisely the production population this deployment refuses.
  v_dur := public.challenge_window_duration();
  select count(*) into v_bad
    from public.death_verification_cases c
    cross join lateral (select public.owner_notice_release_authority(c.id) as a) x
   where (x.a ->> 'notice_accepted_at') is null
     and (x.a -> 'release_eligible_at') is not null
     and (x.a -> 'release_eligible_at') <> 'null'::jsonb;
  if v_bad > 0 then
    raise exception '0060 FAILED [4.3]: % case(s) carry a release_eligible_at with NO acceptance '
      'fact — the clock is still anchored on provenance', v_bad;
  end if;

  if v_dur is not null then
    select count(*) into v_bad
      from public.death_verification_cases c
      cross join lateral (select public.owner_notice_release_authority(c.id) as a) x
     where (x.a ->> 'notice_accepted_at') is not null
       and (x.a ->> 'release_eligible_at')::timestamptz
           is distinct from (x.a ->> 'notice_accepted_at')::timestamptz + v_dur;
    if v_bad > 0 then
      raise exception '0060 FAILED [4.3]: % case(s) have release_eligible_at <> notice_accepted_at '
        '+ challenge_window_duration()', v_bad;
    end if;
  end if;

  -- ── 4.4 NON-VACUITY, REPORTED HONESTLY RATHER THAN ASSERTED ─────────────────────────────────
  --
  -- ★ A GREEN CHECK OVER ZERO ROWS IS NOT A PASS, AND THIS SAYS SO OUT LOUD. On a database with no
  -- death-verification cases §4.2 and §4.3 are vacuous — true, and evidence of nothing. That is
  -- REPORTED rather than silently counted as a pass, and it is not raised as an error either: an
  -- empty database is a legitimate state, and the exhaustive proof lives in the suite regardless.
  if v_cases = 0 then
    raise notice '0060 · 4.2-4.3 SKIPPED-VACUOUS: this database holds no death-verification cases, '
      'so the over-all-cases invariants asserted nothing. The exhaustive A-J proof is in '
      'db/tests/release_safety_authorization.sql §12, run on every replay.';
  else
    raise notice '0060 · 4.2-4.3 evaluated over % real case(s): none reports READY without an '
      'acceptance fact; release_eligible_at is NULL exactly where acceptance is NULL and equals '
      'acceptance + the configured window everywhere else', v_cases;
  end if;

  raise notice '0060 OK (behavioural, READ-ONLY): the authority executes, fails closed on null and '
    'unknown cases, and holds its acceptance and anchor invariants over every case this database '
    'contains. This block writes NOTHING — no auth.users, no estate, no case, no owner notice.';
end $$;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 5 · R13 — THE HISTORICAL PINS, AND HOW EACH WAS RESOLVED
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- Migrations 0056, 0057, 0058 and 0059 each pinned `authorize_release` (and 0056 also
-- `begin_challenge_window`) to text this migration deliberately removes. All FIVE in-migration
-- guards were AMENDED IN THE ASSERTION LAYER ONLY — zero DDL changed in any of them — into
-- supersession-aware forms that remain load-bearing after the cutover:
--
--   0056:begin_challenge_window   OB-1 predicate  OR  OB-2 episode scope       · never neither/both
--   0056:authorize_release        OB-1 predicate  OR  OB-2 acceptance authority · never neither/both
--   0057:authorize_release        OB-1 predicate  OR  OB-2 acceptance authority · never neither/both
--   0058:authorize_release        posture must MATCH whether 0060 is applied (catalog-decided)
--   0059:authorize_release        posture must MATCH whether 0060 is applied (catalog-decided)
--
-- Every one of them is strictly STRONGER than what it replaced: the originals could be satisfied
-- only by the old literal and could not fail on the absence of both predicates; the amendments
-- cannot be satisfied by absence, and cannot be satisfied by a comment either, because each OB-2
-- branch requires `to_regprocedure('public.owner_notice_release_authority(uuid)')` — a catalog fact
-- that no prose can supply.
--
-- ★ THIS BLOCK RE-PROVES THE AMENDMENT FROM THE OTHER SIDE. The guards above run when their own
-- migrations are pasted. This one runs when PHASE D is pasted, and asserts the thing an operator
-- actually needs to know at that moment: that no live guard anywhere in the catalog still demands
-- the superseded literal. Without it, a migration amended in source but pasted from a stale bundle
-- would be discovered only by a replay failure days later.
do $$
declare
  v_n bigint;
begin
  -- Any FUNCTION body still demanding the old literal as a precondition would now be unsatisfiable.
  -- Scoped to the two doors by name: other bodies (the reissue assessment, the censuses) mention
  -- statuses legitimately and are not release preconditions.
  select count(*) into v_n
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public'
     and p.proname in ('authorize_release', 'begin_challenge_window')
     and p.prosrc like '%status <> ''cancelled''%';
  if v_n <> 0 then
    raise exception '0060 FAILED: % release-path routine(s) still carry the superseded OB-1 '
      'predicate. The cutover is half-applied.', v_n;
  end if;

  raise notice '0060 · R13 RESOLVED: five historical self-checks superseded in the assertion layer '
    'only (0056 x2, 0057, 0058, 0059), each now a disjunction that cannot pass on absence and '
    'cannot be satisfied by a comment; no release-path routine still demands the OB-1 literal.';
end $$;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 6 · THE CUTOVER CENSUS — counts only, no ids, no addresses, no estate names
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ A MIGRATION THAT CHANGES THE RELEASE DOOR WITHOUT STATING HOW MANY LIVE ESTATES IT BLOCKS IS A
-- SILENT OPERATIONAL CHANGE. Printed AFTER the cutover has been asserted, so the numbers describe
-- the door that is now deployed. A NOTICE rather than an assertion: a non-zero refused population is
-- not an error, it is the operator's Phase C queue.
do $$
declare
  v_door bigint; v_admit bigint; v_refuse bigint;
  v_legacy bigint; v_renotices bigint;
begin
  select count(*) into v_door from public.estate_lifecycle where state = 'challenge_window';

  select
    count(*) filter (where (public.owner_notice_release_authority(cc.case_id) ->> 'accepted')::boolean),
    count(*) filter (where not coalesce(
      (public.owner_notice_release_authority(cc.case_id) ->> 'accepted')::boolean, false))
    into v_admit, v_refuse
    from (
      select (select c.id from public.death_verification_cases c
               where c.estate_id = l.estate_id and c.status = 'verified'
               order by c.decided_at desc limit 1) as case_id
        from public.estate_lifecycle l
       where l.state = 'challenge_window'
    ) cc;

  select count(*) filter (where o.status = 'dispatched' and o.notice_accepted_at is null),
         count(*) filter (where o.notice_kind = 'death_process.window_renotice')
    into v_legacy, v_renotices
    from public.owner_notice_outbox o
   where o.superseded_by is null and o.channel = 'email';

  raise notice '0060 CUTOVER CENSUS · estates at the release door=% · with a provable acceptance '
    'fact (releasable subject to the clock and the two-person rule)=% · REFUSED by Phase D=% · '
    'current generations still dispatched-with-no-acceptance-fact=% · re-notices issued to date=%',
    v_door, v_admit, v_refuse, v_legacy, v_renotices;

  if v_refuse > 0 then
    raise notice '0060 GATE · % estate(s) at the door now refuse with notice_never_accepted. This '
      'is the Phase C queue: an operator re-notice PRODUCES the missing fact. No manual SQL repair '
      'of a safety table is required, or permitted.', v_refuse;
  end if;
  raise notice '0060 NOTE · notice_accepted_at is PROVIDER ACCEPTANCE. It is not delivery, not '
    'receipt, and not proof that a living owner read anything. Phase D protects on the strongest '
    'persisted provider fact available; it claims no delivery attestation.';
end $$;

commit;
-- ★ If you see an error above and no COMMIT, nothing was applied. Fix the cause and paste again.
